contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to deposit; we require this contract has enough balance to send it
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record balances before
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform deposit on c sending 'amount' wei
        c.deposit{value: amount}();

        // After deposit, the contract balance must have increased by amount
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // Now attempt to withdrawAll as this contract (msg.sender is this test contract)
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // Read credit via the public mapping getter: credit(address)
        // Note: mapping getter signature is credit(address) returns (uint)
        uint creditAfter = c.credit(address(this));

        // General rule (single assert): If withdrawAll did not revert, then
        // 1) c's balance decreased exactly by 'amount'
        // 2) this contract's balance increased exactly by 'amount'
        // 3) and c reports zero credit for this contract
        // Otherwise (if reverted), the balances and credit remain as after deposit
        assert(
            (!reverted && afterC + amount == afterDepositC && afterThis == afterDepositThis + amount && creditAfter == 0)
            || (reverted && afterC == afterDepositC && afterThis == afterDepositThis && creditAfter == c.credit(address(this)))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two parameters: an initial deposit amount and a second attemptWithdraw flag
    // The test will: deposit(amount) from this contract, read address(c).balance and then try withdrawAll(),
    // and assert the general invariant described in property_summary.
    function run(uint amount, bool secondAttempt) public payable {
        require(true);
        // Ensure this contract has enough balance to deposit 'amount' if we use value send
        if (amount > 0) {
            require(address(this).balance >= amount);
            c.deposit{value: amount}();
        } else {
            // allow zero deposit as well
            c.deposit{value: 0}();
        }

        // Observe balance of c after deposit
        uint balAfterDeposit = address(c).balance;

        // Read credit via the auto-generated getter: credit(address) is public? Note: in C it's declared `mapping (address => uint) credit;` (not public)
        // The contract's credit mapping is not public, so we cannot read it. Instead observe effect by attempting withdraw and checking address balances and whether withdraw reverted.
        // We'll perform withdrawAll and capture whether it reverted.
        bool reverted1;
        uint balBeforeWithdraw = balAfterDeposit;
        uint myBalBefore = address(this).balance;
        try c.withdrawAll() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        uint balAfterWithdraw = address(c).balance;
        uint myBalAfter = address(this).balance;

        // Optionally do a second attempt to exercise repeated calls
        bool reverted2 = false;
        uint balAfterSecond = balAfterWithdraw;
        uint myBalAfterSecond = myBalAfter;
        if (secondAttempt) {
            try c.withdrawAll() {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            balAfterSecond = address(c).balance;
            myBalAfterSecond = address(this).balance;
        }

        // Assertion: withdrawAll cannot increase c's ether balance. If first call succeeded then caller's balance cannot be less than before (i.e., it should increase by the amount withdrawn), and c's balance must not have increased.
        // Because we cannot read credit mapping, we assert a general rule about address(c).balance and address(this).balance monotonicity relative to the withdraw outcome(s).
        // Formalize: balAfterWithdraw <= balBeforeWithdraw and balAfterSecond <= balAfterWithdraw
        // And if withdraw did not revert then myBalAfter >= myBalBefore, and if secondAttempt did not revert then myBalAfterSecond >= myBalAfter.
        assert(
            balAfterWithdraw <= balBeforeWithdraw
            && balAfterSecond <= balAfterWithdraw
            && (reverted1 || myBalAfter >= myBalBefore)
            && (secondAttempt ? (reverted2 || myBalAfterSecond >= myBalAfter) : true)
        );
    }

    // Allow receiving Ether from c when it sends funds in withdrawAll
    receive() external payable { }
}

