contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs to drive contract
    // depositAmount: amount to deposit into c
    // doWithdraw: whether to call withdrawAll after deposit
    function run(uint depositAmount, bool doWithdraw) public payable {
        // ensure this test contract has enough balance to deposit
        require(address(this).balance >= depositAmount);

        // observe C's balance before any action
        uint cBalanceBefore = address(c).balance;
        // observe this contract's balance before any action
        uint selfBalanceBefore = address(this).balance;

        // perform deposit to set up state (top-level state-changing call)
        c.deposit{value: depositAmount}();

        // observe balances after deposit
        uint cBalanceAfterDeposit = address(c).balance;
        uint selfBalanceAfterDeposit = address(this).balance;

        // perform withdrawAll optionally, capturing whether it reverted
        bool withdrawReverted = false;
        if (doWithdraw) {
            try c.withdrawAll() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        }

        // observe balances after possible withdraw
        uint cBalanceFinal = address(c).balance;
        uint selfBalanceFinal = address(this).balance;

        // General rule:
        // 1) deposit increases C's balance by depositAmount and decreases this contract's balance by depositAmount;
        // 2) if withdrawAll was called and reverted, balances remain equal to post-deposit balances;
        //    if withdrawAll was called and succeeded, then this contract's balance is >= post-deposit balance
        //    and C's balance is <= post-deposit balance, and the decrease in C's balance equals the increase
        //    in this contract's balance (no other parties gain Ether).
        assert(
            // deposit effect
            cBalanceAfterDeposit == cBalanceBefore + depositAmount
            && selfBalanceAfterDeposit == selfBalanceBefore - depositAmount

            // withdraw effect
            && (
                !doWithdraw
                ? (cBalanceFinal == cBalanceAfterDeposit && selfBalanceFinal == selfBalanceAfterDeposit)
                : (
                    withdrawReverted
                    ? (cBalanceFinal == cBalanceAfterDeposit && selfBalanceFinal == selfBalanceAfterDeposit)
                    : (
                        // on success: this contract's balance did not decrease compared to post-deposit,
                        // C's balance did not increase compared to post-deposit,
                        // and the delta of C equals negative delta of this contract
                        selfBalanceFinal >= selfBalanceAfterDeposit
                        && cBalanceFinal <= cBalanceAfterDeposit
                        && (cBalanceAfterDeposit - cBalanceFinal) == (selfBalanceFinal - selfBalanceAfterDeposit)
                      )
                  )
              )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two parameters: an amount to deposit and a second amount that we may attempt to withdraw (unused here
    // except to allow varied inputs). The function is payable because we will forward Ether to c.deposit.
    function run(uint depositAmount, uint /*unused*/) public payable {
        require(address(this).balance >= depositAmount);

        // Read initial observable values
        uint beforeCBalance = address(c).balance;

        // Perform deposit: must be a top-level state-changing call
        c.deposit{value: depositAmount}();

        // After deposit, c's balance must have increased by exactly depositAmount
        uint afterCBalance = address(c).balance;

        // Now attempt withdrawAll and observe whether it reverts
        bool didRevert;
        try c.withdrawAll() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // If withdrawAll did not revert, then after a successful withdraw the contract's balance cannot be greater than it was immediately after deposit
        // and cannot be less than before deposit (i.e., at most depositAmount was removed).
        // If it reverted, the balance must remain equal to afterCBalance.
        // The general rule we assert is: after deposit, the change in c.balance is between 0 and +depositAmount (inclusive)
        // and if withdrawAll succeeded it decreased by at most depositAmount.
        // Formulated without underflow: afterCBalance >= beforeCBalance and (didRevert ? address(c).balance == afterCBalance : address(c).balance + depositAmount >= afterCBalance && address(c).balance <= afterCBalance)

        assert(
            // deposit increased c.balance by exactly depositAmount
            afterCBalance == beforeCBalance + depositAmount
            && (
                // if reverted, c.balance unchanged
                (didRevert && address(c).balance == afterCBalance)
                ||
                // if not reverted, c.balance is <= afterCBalance and >= afterCBalance - depositAmount
                (!didRevert && address(c).balance <= afterCBalance && address(c).balance + depositAmount >= afterCBalance)
            )
        );
    }

    receive() external payable {}
}

