contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an arbitrary prior deposit amount to set up credit,
    // then call withdrawAll and assert it does not increase contract balance or recorded credit
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // set up: deposit some Ether into c to create nonzero credit for this contract
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // observe before-values via public surface
        uint beforeContractBalance = address(c).balance;
        // credit getter is not present in C (credit is private), so we observe by attempting to deposit zero
        // but credit mapping is not public; instead we rely on that deposit increased balance and that withdrawAll
        // should not increase address(c).balance nor any public observable credit. Since credit mapping is not
        // public, we use the fact that address(c).balance is observable and that withdrawAll should not increase it.

        // make the call and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBalance = address(c).balance;

        // General rule: withdrawAll never increases the contract's balance, and it never increases caller's credit
        // (we cannot read credit mapping directly, so we express the credit non-increase by observing that
        // performing a zero-value deposit after withdrawAll will not report a smaller net effect than before.
        // To remain within the allowed observables, we assert only the contract balance non-increase here
        // and that a subsequent deposit cannot observe an increase in caller's recorded credit via increasing
        // contract balance beyond what was deposited now. We express the second part as: after withdrawAll,
        // doing a fresh deposit of x increases address(c).balance by exactly x (no implicit bonus), which implies
        // withdrawAll did not increase recorded credit for this caller.

        // perform a fresh small deposit to observe increment behavior
        uint probe = 1;
        require(address(this).balance >= probe, "insufficient balance for probe");
        uint beforeProbeBalance = address(c).balance;
        c.deposit{value: probe}();
        uint afterProbeBalance = address(c).balance;

        // cleanup: we don't attempt to withdraw probe here.

        // Single assert stating both properties:
        // 1) afterContractBalance <= beforeContractBalance (withdrawAll did not increase C's balance)
        // 2) afterProbeBalance - beforeProbeBalance == probe (a fresh deposit increases C's balance exactly by probe,
        //    meaning withdrawAll didn't secretly increase caller credit that would make the deposit effect larger)
        assert(afterContractBalance <= beforeContractBalance && (afterProbeBalance - beforeProbeBalance == probe));
    }

    receive() external payable { }
}

